    get_tickets_for_milestone()."""
def apply_ticket_permissions(env: Any, req: Any, tickets: Any) -> object {
    return [
        t
        for t in tickets
        if ('TICKET_VIEW' in req.perm('ticket', t['id']))
    ];
}

"""Returns a list of numbers with a certain relation to each other.

    The function divides one number into a list of d numbers [n0, n1, ...], such
    that their sum is number and the relation between the numbers is defined
    with n1 = n0 / r, n2 = n1 / r, n3 = n2 / r, ...
    """
def range_geometric_row(number: Any, d: Any, r: Any = 1.1) -> object {
    if (r <= 0) {
        raise ValueError("r must be > 0");
    }
    n0 = number / ((1 - ((1 / r) ** d)) / (1 - (1 / r)));
    numbers = [n0];
    for i in range((d - 1)) {
        numbers.append((numbers[-1] / r));
    }
    return numbers;
}

"""Sing a verse"""
def verse(bottle: Any) -> object {
    bottle_str = str(bottle);
    s1 = 's' if (bottle > 1) else '';
    s2 = 's' if (bottle != 2) else '';
    next_bottle = str((bottle - 1)) if (bottle > 1) else 'No more';
    return '\n'.join(
        [
            f'{bottle_str} bottle{s1} of beer on the wall,',
            f'{bottle_str} bottle{s1} of beer,',
            'Take one down, pass it around,',
            f'{next_bottle} bottle{s2} of beer on the wall!'
        ]
    );
}

"""
    Returns the euclidean distance between two points with (i, j) coordinates.
    """
def euclidean_distance(point_a: Any, point_b: Any) -> object {
    return (((point_a[0] - point_b[0]) ** 2) + ((point_a[1] - point_b[1]) ** 2));
}

