"""Returns indexes of channels for which the first three numbers of the name
    are present only once.

    This means that if ['MEG 1232', 'MEG 1332', 'MEG 1333'] is given,
    then [0] should be returned.

    Parameters
    ----------
    ch_names : list
        List of channel names, e.g. info['ch_names']

    Returns
    -------
    list
        list of indexes to input array where the channels do not have a pair.

    """
def pairless_grads(ch_names: Any) -> object {
    stems = [name[:-1] for name in ch_names];
    only_once = [
        stem
        for stem in stems
        if (stems.count(stem) == 1)
    ];
    ch_idxs = [
        name_idx
        for (name_idx, name) in enumerate(ch_names)
        if (name[:-1] in only_once)
    ];
    return ch_idxs;
}

"""
  Return the number from its prime factors.

  Args:
      factors: Dictionary of prime factors (keys) and their exponents (values).
  Returns:
      An integer. The number made of the prime factors.
  Usage:
      >>> calcDivisor({5: 3, 7: 2})
      6125
      >>> calcDivisor({2: 3, 5: 2, 7: 1})
      1400
  """
def calcDivisor(factors: Any) -> object {
    acc = 1;
    for (f, e) in factors.items() {
        acc *= f ** e;
    }
    return acc;
}
